#requires -Version 5.1
param([switch]$Execute, [int]$ExpectedOldPid, [string]$ExpectedOldTicks)
if (!$Execute) { throw 'Default-off draft: explicit -Execute and expected old identity required' }
if ($ExpectedOldPid -ne 5968 -or $ExpectedOldTicks -cne '639242578556279623') { throw 'Caller old identity does not match reviewed target' }
# REVIEW DRAFT. No CAD files opened. Explicit invocation closes the pinned empty
# existing session, then starts and gracefully closes one retained native child.
$ErrorActionPreference = 'Stop'
$folder = $PSScriptRoot
$exe = 'C:\Program Files\SOLIDWORKS 2022\SOLIDWORKS\SLDWORKS.exe'
$exeHash = '6384c0829bac149831be5fdc9e705c90612273d25b46fdff5e5760d11e22d6cc'
$helper = Join-Path $folder 'NativeSessionProbe.exe'
$helperHash = '54e077e7af0648f00d51beeb45b8ef5b252fc695667cd519678e4c61af5e62ac'
$owned = Join-Path $folder 'OwnedProcess.ps1'
if ((Get-FileHash -LiteralPath $owned).Hash.ToLowerInvariant() -ne 'd4d08e782b492cc167924d5a04f927970e191102828aae65b7da43393e6cf23e') { throw 'helper source drift' }
. $owned
$resultPath = Join-Path $folder 'lifecycle-result.json'
if (Test-Path -LiteralPath $resultPath) { throw 'Attempt already exists; no retry' }
$r = [ordered]@{ utc=[DateTime]::UtcNow.ToString('o'); outcome='in_progress'; stage='preflight';
 caller=@{execute=$Execute.IsPresent;expectedOldPid=$ExpectedOldPid;expectedOldTicks=$ExpectedOldTicks}; oldOwned=$false; nativeStartAttempted=$false; nativeStarted=$false; nativeExit=$null;
 recovery_required=$false; error=$null; observations=@(); qualification='incomplete' }
$old = $null
$native = $null
# Acquire the actual OS handle so PID reuse cannot substitute another process.
function Read-Identity($Process) {
 $null = $Process.Handle
 [ordered]@{pid=$Process.Id; ticks=$Process.StartTime.ToUniversalTime().Ticks.ToString();
 session=$Process.SessionId; path=$Process.MainModule.FileName}
}
function Save-Receipt {
 $r | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $resultPath -Encoding UTF8
}
function Assert-Identity($Process, $Identity) {
 $all = @(Get-Process SLDWORKS -ErrorAction SilentlyContinue)
 try {
  if ($all.Count -ne 1 -or $all[0].Id -ne $Identity.pid -or $Process.HasExited) { throw 'singleton or exit mismatch' }
  $now = Read-Identity $Process
  if ($now.pid -ne $Identity.pid -or $now.ticks -cne $Identity.ticks -or
      $now.session -ne $Identity.session -or $now.session -ne [Diagnostics.Process]::GetCurrentProcess().SessionId -or
      $now.path -ine $exe) { throw 'native identity mismatch' }
  $v = [Diagnostics.FileVersionInfo]::GetVersionInfo($exe)
  if ($v.FileVersion -ne '30.5.0.0049' -or $v.ProductVersion -ne '30.5.0.0049' -or
      (Get-FileHash -LiteralPath $exe).Hash.ToLowerInvariant() -ne $exeHash) { throw 'native binary mismatch' }
 } finally { foreach ($p in $all) { $p.Dispose() } }
}
function Probe($Mode, $Process, $Identity, $Label) {
 Assert-Identity $Process $Identity
 if ((Get-FileHash -LiteralPath $helper).Hash.ToLowerInvariant() -ne $helperHash) { throw 'probe binary drift' }
 $r.stage=$Label; Save-Receipt
 $obs = Invoke-OwnedProcess -Executable $helper -Arguments @($Mode,[string]$Identity.pid,$Identity.ticks,[string]$Identity.session) -TimeoutMs 30000 -LogBase (Join-Path $folder $Label)
 $r.observations += $obs; Save-Receipt
 if ($obs.timedOut -or $obs.error -or $obs.exitCode -ne 0) { throw ('Probe failed: '+$Label) }
 $data = $obs.stdout | ConvertFrom-Json
 if ($data.outcome -ne 'passed' -or $data.apiPid -ne $Identity.pid -or
     $data.expectedTicks -cne $Identity.ticks -or $data.documentCount -ne 0 -or $data.releaseError) { throw 'probe evidence mismatch' }
}
try {
 Save-Receipt
 if (![Environment]::Is64BitProcess -or $PSVersionTable.PSVersion.Major -ne 5) { throw 'Requires x64 PS5.1' }
 $interop = 'C:\Program Files\SOLIDWORKS 2022\SOLIDWORKS\api\redist\SolidWorks.Interop.sldworks.dll'
 if ((Get-FileHash -LiteralPath $interop).Hash.ToLowerInvariant() -ne '9284fcfb569b3e7e906e7c8d1f551e6d073f79500ba78e32c6464a53571813f0') { throw 'interop drift' }
 $old = [Diagnostics.Process]::GetProcessById(5968)
 $r.old = Read-Identity $old
 if ($r.old.ticks -cne '639242578556279623' -or $r.old.session -ne 1) { throw 'old session changed' }
 Probe 'inspect' $old $r.old 'old-inspect'
 Probe 'graceful-close-empty' $old $r.old 'old-close'
 $r.stage='wait_old_exit'; Save-Receipt
 if (!$old.WaitForExit(30000)) { throw 'old exit unconfirmed; do not start' }
 $r.oldExit=$old.ExitCode; Save-Receipt; if ($r.oldExit -ne 0) { throw 'old native nonzero exit' }
 $remaining=@(Get-Process SLDWORKS -ErrorAction SilentlyContinue)
 try { if ($remaining.Count -ne 0) { throw 'native process still present' } }
 finally { foreach ($p in $remaining) { $p.Dispose() } }
 if ((Get-FileHash -LiteralPath $exe).Hash.ToLowerInvariant() -ne $exeHash) { throw 'launch binary drift' }
 $native = New-Object Diagnostics.Process
 $native.StartInfo.FileName=$exe
 $native.StartInfo.WorkingDirectory=$folder
 $native.StartInfo.UseShellExecute=$false
 $native.StartInfo.CreateNoWindow=$true
 $native.StartInfo.WindowStyle=[Diagnostics.ProcessWindowStyle]::Hidden
 $r.stage='start_native'; $r.nativeStartAttempted=$true; Save-Receipt
 if (!$native.Start()) { throw 'native start false' }
 $r.nativeStarted=$true; $r.nativePid=$native.Id; Save-Receipt
 $r.native=Read-Identity $native; Save-Receipt
 # One bounded GUI-idle wait, then one API probe. Idle is not claimed as COM readiness.
 if (!$native.WaitForInputIdle(60000)) { throw 'native readiness unconfirmed' }
 Probe 'inspect' $native $r.native 'owned-inspect'
 Probe 'graceful-close-empty' $native $r.native 'owned-close'
 $r.stage='wait_owned_exit'; Save-Receipt
 if (!$native.WaitForExit(30000)) { throw 'owned native exit unconfirmed' }
 $r.nativeExit=$native.ExitCode
 if ($r.nativeExit -ne 0) { throw 'owned native nonzero exit' }
 $remaining=@(Get-Process SLDWORKS -ErrorAction SilentlyContinue)
 try { if ($remaining.Count -ne 0) { throw 'unexpected final native process' } }
 finally { foreach ($p in $remaining) { $p.Dispose() } }
 $r.outcome='passed'
} catch {
 $r.outcome='failed'; $r.error=$_.Exception.Message; $r.recovery_required=$true
} finally {
 # NEVER force-stop native processes. Retain observations even on partial startup.
 if ($native -and $r.nativeStarted) {
  try { $r.nativeHasExited=$native.HasExited; if ($native.HasExited) { $r.nativeExit=$native.ExitCode } }
  catch { $r.nativeObservationError=$_.Exception.Message; $r.recovery_required=$true }
 }
 try { Save-Receipt } finally {
  if ($old) { $old.Dispose() }; if ($native) { $native.Dispose() }
 }
}
if ($r.outcome -ne 'passed') { exit 2 }
exit 0

